Object.assign(window.TEM8_DICTIONARY, {"furniture":{"media":{"uk":"media/uk/furniture__gb_1.mp3","us":"media/us/furniture__us_1.mp3"},"oxford":{"phon":"ˈfɜːnɪtʃə(r)","pos":"noun","senses":[{"en":"objects that can be moved, such as tables, chairs and beds, that are put into a house or an office to make it suitable for living or working in","cn":"（可移动的）家具","ex":{"en":"garden/office furniture","cn":"花园／办公家具"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"家具","en":"Furniture consists of large objects such as tables, chairs, or beds that are used in a room for sitting or lying on or for putting things on or in.","ex":{"en":"Each piece of furniture in their home suited the style of the house.","cn":"他们家里的每件家具都和房子的风格相得益彰。"}},{"pos":"PHRASE 短语","cn":"被认作当然的人(或事物);习以为常的人(或事物)","en":"If you describe someone or something as part of the furniture, you are suggesting that they have been somewhere such as their place of work for such a long time that it is hard to imagine that place without them."}]},"examples":[{"en":"We need to buy some new furniture.","cn":"我们需要买一些新家具。"},{"en":"garden/office, etc. furniture","cn":"花园、办公室等处的家具"}]},"furnished":{"media":{"uk":"media/uk/furnished__gb_1.mp3","us":"media/us/furnished__us_1.mp3"},"oxford":{"phon":"ˈfɜːnɪʃt","pos":"adjective","senses":[{"en":"containing furniture","cn":"配备家具的","ex":{"en":"furnished accommodation (= to rent complete with furniture)","cn":"连家具出租房"}}]},"examples":[{"en":"The house was simply furnished.","cn":"这房子陈设简单。"},{"en":"furnished accommodation (= to rent complete with furniture)","cn":"连家具出租房"}]},"fund":{"media":{"uk":"media/uk/fund__gb_1.mp3","us":"media/us/fund__us_1.mp3"},"oxford":{"phon":"fʌnd","pos":"noun","senses":[{"en":"an amount of money that has been saved or has been made available for a particular purpose","cn":"基金；专款","g":"[countable]","ex":{"en":"a disaster relief fund","cn":"赈灾专款"}},{"en":"money that is available to be spent","cn":"资金；现款","g":"[plural]","lab":"informal","ex":{"en":"government/federal funds","cn":"政府／联邦资金"}},{"en":"a company that manages money for people by investing it; the money managed by such a company","cn":"基金公司；基金","g":"[countable]","lab":"finance","ex":{"en":"Any extra money that James saves should go into a money market fund.","cn":"詹姆斯节省的任何额外资金都应该投入货币市场基金。"}},{"en":"an amount or a supply of something","cn":"（相当的）数量；储备","g":"[singular]","ex":{"en":"a fund of knowledge","cn":"丰富的知识"}},{"en":"to provide money for something, usually something official","cn":"为…提供资金；拨款给","ex":{"en":"Who is funding this research?","cn":"谁在资助这项研究？"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"(尤指为某一特定目的给予的)资金，钱款","en":"Funds are amounts of money that are available to be spent, especially money that is given to an organization or person for a particular purpose.","ex":{"en":"The concert will raise funds for research into Aids.","cn":"这场音乐会将为艾滋病研究筹款。"}},{"pos":"N-COUNT 可数名词","cn":"(某一特定的)基金，专款","en":"A fund is an amount of money that is collected or saved for a particular purpose.","ex":{"en":"...a pension fund.","cn":"养老基金"}},{"pos":"VERB 动词","cn":"资助;为…提供资金","en":"When a person or organization funds something, they provide money for it.","ex":{"en":"The Bush Foundation has funded a variety of faculty development programs","cn":"布什基金会已经资助了许多教员发展项目。"}},{"pos":"N-COUNT 可数名词","cn":"大量;充足","en":"If you have a fund of something, you have a lot of it.","ex":{"en":"He is possessed of an extraordinary fund of energy.","cn":"他的精力异常充沛。"}}]},"examples":[{"en":"The hospital is trying to raise funds for a new kidney machine.","cn":"这家医院正设法募集资金购买一台新的血液透析器。"},{"en":"The project has been cancelled because of lack of funds.","cn":"这个项目因缺乏资金已经撤销。"}]},"furred":{"media":{"uk":"media/uk/furred__gb_1.mp3","us":"media/us/furred__us_1.mp3"},"oxford":{"phon":"fɜːd","pos":"adjective","senses":[{"en":"covered with fur or with something that looks like fur","cn":"覆盖毛皮的；穿戴毛皮衣物的；长舌苔的","ex":{"en":"a furred tongue","cn":"长苔的舌头"}}]},"examples":[{"en":"a furred tongue","cn":"长苔的舌头"}]},"funny":{"media":{"uk":"media/uk/funny__gb_1.mp3","us":"media/us/funny__us_1.mp3"},"oxford":{"phon":"ˈfʌni","pos":"adjective","senses":[{"en":"making you laugh","cn":"滑稽的；好笑的","lab":"ironic","sc":"amusing","ex":{"en":"a funny story/joke","cn":"有趣的故事／笑话"}},{"en":"difficult to explain or understand; strange and not as you expect","cn":"奇怪的；费解的；出乎意料的","sc":"strange","ex":{"en":"A funny thing happened to me today.","cn":"今天我碰上了一件奇怪的事。"}},{"en":"seeming or likely to be wrong, illegal or dishonest","cn":"可疑的；非法的；不诚实的","lab":"informal","sc":"wrong/illegal","ex":{"en":"I suspect there may be something funny going on.","cn":"我怀疑可能有某种非法勾当在进行。"}},{"en":"humorous in a way that shows a lack of respect for somebody","cn":"嬉皮笑脸的；放肆的","lab":"British English","sc":"without respect","ex":{"en":"Don't you get funny with me!","cn":"你不要对我放肆！"}},{"en":"slightly ill","cn":"小病的；微恙的；稍有不适的","lab":"informal","sc":"ill/sick","ex":{"en":"I feel a bit funny today—I don't think I'll go to work.","cn":"我今天感到有点不舒服，不想去上班了。"}},{"en":"slightly crazy or strange","cn":"疯疯癫癫的；不很正常的","lab":"British English, informal，，","sc":"crazy","ex":{"en":"That Dave's a funny chap, isn't he?","cn":"那个戴夫疯疯癫癫的，是不是？"}},{"en":"not working as it should","cn":"出故障的","lab":"informal","sc":"machine","ex":{"en":"My computer keeps going funny.","cn":"我的计算机老出故障。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有趣的;好笑的;滑稽的","en":"Someone or something that is funny is amusing and likely to make you smile or laugh.","ex":{"en":"Wade was smart and not bad-looking, and he could be funny when he wanted to","cn":"韦德脑子聪明，相貌也不难看，而且如果他愿意的话还很风趣。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"古怪的;奇怪的;令人困惑的","en":"If you describe something as funny, you think it is strange, surprising, or puzzling.","ex":{"en":"Children get some very funny ideas sometimes!","cn":"小孩子的想法有时候真是稀奇古怪！"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"略感不适的","en":"If you feel funny, you feel slightly ill.","ex":{"en":"My head had begun to ache and my stomach felt funny.","cn":"我的头开始疼起来，胃也有些不舒服。"}},{"pos":"N-PLURAL 复数名词","cn":"(报刊上的)幽默漫画,滑稽连环漫画","en":"The funnies are humorous drawings or a series of humorous drawings in a newspaper or magazine."},{"pos":"PHRASE 短语","cn":"不端行为;见不得人的勾当","en":"Funny business is dishonest or unacceptable behaviour.","ex":{"en":"...an inquiry into funny business in Ireland's biggest export industry.","cn":"对爱尔兰最大的出口行业违规行为的调查"}}]},"examples":[{"en":"I was really embarrassed, but then I saw the funny side of it.","cn":"我确实感到尴尬，但接着我发现了事情好笑的一面。"},{"en":"I'm pleased I didn't get that job, in a funny sort of way.","cn":"我没有得到那份工作，但我有一种说不清楚的高兴。"}]},"functionality":{"media":{"uk":"media/uk/functionality__gb_1.mp3","us":"media/us/functionality__us_1.mp3"},"oxford":{"phon":"ˌfʌŋkʃəˈnæləti","pos":"noun","senses":[{"en":"the quality in something of being very suitable for the purpose it was designed for","cn":"实用；符合实际","g":"[uncountable]"},{"en":"the purpose that something is designed for or expected to perform","cn":"设计目的；设计功能","g":"[uncountable]","ex":{"en":"Manufacturing processes may be affected by the functionality of the product.","cn":"生产过程可能要受到产品设计目的的影响。"}},{"en":"the range of functions that a computer or other electronic system can perform","cn":"（计算机或电子系统的）功能性","g":"[uncountable, countable]","lab":"computing","ex":{"en":"new software with additional functionality","cn":"有附加功能的新软件"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(计算机等的)功能性","en":"The functionality of a computer or other machine is how useful it is or how many functions it can perform.","ex":{"en":"It is significantly more compact than any comparable laptop, with no loss in functionality.","cn":"它比同类笔记本电脑小巧很多，但功能未减。"}}]},"examples":[{"en":"Manufacturing processes may be affected by the functionality of the product.","cn":"生产过程可能要受到产品设计目的的影响。"},{"en":"new software with additional functionality","cn":"有附加功能的新软件"}]},"funeral":{"media":{"uk":"media/uk/funeral__gb_1.mp3","us":"media/us/funeral__us_1.mp3"},"oxford":{"phon":"ˈfjuːnərəl","pos":"noun","senses":[{"en":"a ceremony, often a religious one, for burying or cremating (= burning) a dead person","cn":"葬礼；丧礼；出殡","ex":{"en":"Hundreds of people attended the funeral.","cn":"数百人参加了葬礼。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"葬礼;丧礼","en":"A funeral is the ceremony that is held when the body of someone who has died is buried or cremated.","ex":{"en":"His funeral will be on Thursday at Blackburn Cathedral","cn":"他的葬礼将于星期四在布莱克本大教堂举行。"}},{"pos":"PHRASE 短语","cn":"这是你自作自受;那你可要倒霉了","en":"If someone says to you 'It's your funeral', they think your decision or your actions will have bad consequences for you, but they are unwilling to interfere.","ex":{"en":"None of my business, I guess. It's your funeral.","cn":"我想是不关我什么事儿，你就自寻死路吧。"}}]},"examples":[{"en":"Hundreds of people attended the funeral.","cn":"数百人参加了葬礼。"},{"en":"a funeral march (= a sad piece of music suitable for funerals)","cn":"丧礼进行曲"}]},"furtive":{"media":{"uk":"media/uk/furtive__gb_1.mp3","us":"media/us/furtive__us_1.mp3"},"oxford":{"phon":"ˈfɜːtɪv","pos":"adjective","senses":[{"en":"behaving in a way that shows that you want to keep something secret and do not want to be noticed","cn":"偷偷摸摸的；鬼鬼祟祟的；遮遮掩掩的","ex":{"en":"She cast a furtive glance over her shoulder.","cn":"她偷偷往背后瞥了一下。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"偷偷摸摸的;鬼鬼祟祟的;秘密的","en":"If you describe someone's behaviour as furtive, you disapprove of them behaving as if they want to keep something secret or hidden.","ex":{"en":"With a furtive glance over her shoulder, she unlocked the door and entered the house.","cn":"她鬼鬼祟祟地往身后扫了一眼，然后打开门锁进了房子。"}}]},"examples":[{"en":"He looked sly and furtive.","cn":"他显得偷偷摸摸，鬼鬼祟祟。"},{"en":"She cast a furtive glance over her shoulder.","cn":"她偷偷往背后瞥了一下。"}]},"fulfilling":{"oxford":{"phon":"fʊlˈfɪlɪŋ","pos":"adjective","senses":[{"en":"causing somebody to feel satisfied and useful","cn":"让人感觉有意义的；令人满足的","ex":{"en":"a fulfilling experience","cn":"有成就感的经历"}}]},"media":{"uk":"media/uk/fulfilling__gb_1.mp3","us":"media/us/fulfilling__us_1.mp3"},"examples":[{"en":"a fulfilling experience","cn":"有成就感的经历"},{"en":"Nursing is still one of the most fulfilling careers.","cn":"护理仍是最令人有成就感的职业之一。"}],"base":"fulfil"},"fumbling":{"media":{"uk":"media/uk/fumbling__gb_1.mp3","us":"media/us/fumbling__us_1.mp3"},"oxford":{"phon":"ˈfʌmblɪŋ","pos":"adjective","senses":[{"en":"hesitating or uncertain","cn":"迟疑的；笨拙的","ex":{"en":"a fumbling schoolboy","cn":"笨拙的男生"}}]},"examples":[{"en":"a fumbling schoolboy","cn":"笨拙的男生"},{"en":"She dressed, her cold fingers fumbling with the buttons.","cn":""}]},"fury":{"media":{"uk":"media/uk/fury__gb_1.mp3","us":"media/us/fury__us_1.mp3"},"oxford":{"phon":"ˈfjʊəri","pos":"noun","senses":[{"en":"extreme anger that often includes violent behaviour","cn":"狂怒；暴怒；狂暴；大发雷霆","g":"[uncountable]","lab":"figurative","ex":{"en":"Her eyes blazed with fury.","cn":"她的双眼迸发出暴怒之火。"}},{"en":"a state of being extremely angry about something","cn":"狂怒；暴怒","g":"[singular]","ex":{"en":"He flew into a fury when I refused.","cn":"我拒绝，他就勃然大怒。"}},{"en":"(in ancient Greek stories) three goddesses who punish people for their crimes","cn":"（古希腊神话）复仇三女神","g":"[plural]"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"狂怒;暴怒","en":"Fury is violent or very strong anger.","ex":{"en":"She screamed, her face distorted with fury and pain.","cn":"她尖叫着，脸部因狂怒和痛苦而扭曲。"}},{"pos":"PHRASE 短语","cn":"异常愤怒;怒不可遏","en":"If you are in a fury, you are very angry.","ex":{"en":"I had reacted in a fury of grief","cn":"我的反应是悲愤交加。"}}]},"examples":[{"en":"Fury over tax increases (= as a newspaper headline ).","cn":"对增税极端愤怒（作报纸标题）。"},{"en":"( figurative ) There was no shelter from the fury of the storm.","cn":"那时没有地方可以躲避狂风暴雨。"}]},"functioning":{"lemma":"function","media":{"uk":"media/uk/function__gb_1.mp3","us":"media/us/function__us_1.mp3"}},"fuel":{"media":{"uk":"media/uk/fuel__gb_1.mp3","us":"media/us/fuel__us_1.mp3"},"oxford":{"phon":"ˈfjuːəl","pos":"noun","senses":[{"en":"any material that produces heat or power, usually when it is burnt","cn":"燃料","g":"[uncountable, countable]","ex":{"en":"diesel/jet/rocket fuel","cn":"柴油／喷气／火箭燃料"}},{"en":"a thing that is said or done that makes something, especially an argument, continue or get worse","cn":"（尤指使争论等继续或更加激烈的）刺激性言行","g":"[uncountable]","ex":{"en":"The new information adds fuel to the debate over safety procedures.","cn":"新信息对于有关安全程序的辩论是火上浇油。"}},{"en":"to supply something with material that can be burnt to produce heat or power","cn":"给…提供燃料","g":"[transitive]","ex":{"en":"Uranium is used to fuel nuclear plants.","cn":"铀用作核电厂的燃料。"},"pos":"verb"},{"en":"to put petrol into a vehicle","cn":"给（交通工具）加油","g":"[transitive, intransitive]","ex":{"en":"The helicopter was already fuelled (up) and ready to go.","cn":"直升机已加好油，准备起飞。"},"pos":"verb"},{"en":"to increase something; to make something stronger","cn":"增加；加强；刺激","g":"[transitive]","ex":{"en":"to fuel rumours/fears/suspicions","cn":"煽动谣言/恐惧/怀疑"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"燃料","en":"Fuel is a substance such as coal, oil, or petrol that is burned to provide heat or power.","ex":{"en":"They ran out of fuel.","cn":"他们的燃料用完了。"}},{"pos":"VERB 动词","cn":"刺激;使变得更糟;使加剧","en":"To fuel a situation means to make it become worse or more intense.","ex":{"en":"The result will inevitably fuel speculation about the Prime Minister's future","cn":"这一结果将不可避免地加剧人们对首相未来的揣测。"}},{"pos":"PHRASE 短语","cn":"(对…)火上浇油","en":"If something adds fuel to a conflict or debate, or adds fuel to the fire, it makes the conflict or debate more intense.","ex":{"en":"His comments are bound to add fuel to the debate","cn":"他的话必将为争论推波助澜。"}}]},"examples":[{"en":"The revelations gave new fuel to angry opponents of the proposed law.","cn":"新披露的情况使反对该法律提案的人更为激愤。"},{"en":"The new information adds fuel to the debate over safety procedures.","cn":"新信息对于有关安全程序的辩论是火上浇油。"}]},"fun":{"media":{"uk":"media/uk/fun__gb_1.mp3","us":"media/us/fun__us_1.mp3"},"oxford":{"phon":"fʌn","pos":"noun","senses":[{"en":"the feeling of enjoying yourself; activities that you enjoy","cn":"开心；乐趣；好玩的事","ex":{"en":"We had a lot of fun at Sarah's party.","cn":"我们在萨拉的聚会上玩得很开心。"}},{"en":"behaviour or activities that are not serious but are meant to be enjoyed","cn":"嬉戏；逗乐；玩笑","ex":{"en":"She's very lively and full of fun.","cn":"她很活泼，挺有趣的。"}},{"en":"that you enjoy","cn":"逗乐的；有趣的；使人快乐的","ex":{"en":"She's really fun to be with.","cn":"和她在一起真开心。"},"pos":"adjective"},{"en":"that provides entertainment or leisure activities","cn":"享乐；乐趣；快乐；享乐的事","g":"[only before noun]","ex":{"en":"a family fun day","cn":"家庭欢乐的一天"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"趣事;乐趣","en":"You refer to an activity or situation as fun if you think it is pleasant and enjoyable and it causes you to feel happy.","ex":{"en":"This year promises to be terrifically good fun","cn":"今年一定会非常有意思。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"有趣的人;好玩的人","en":"If you say that someone is fun, you mean that you enjoy being with them because they say and do interesting or amusing things.","ex":{"en":"Liz was wonderful fun to be with.","cn":"莉兹是个非常有趣的伙伴。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人愉快的;让人开心的;有趣的","en":"If you describe something as a fun thing, you mean that you think it is enjoyable. If you describe someone as a fun person, you mean that you enjoy being with them.","ex":{"en":"It was a fun evening","cn":"那个晚上令人愉快。"}},{"pos":"PHRASE 短语","cn":"荒唐可笑的人;引人嘲笑的人","en":"Someone who is a figure of fun is considered ridiculous, so that people laugh at them or make jokes about them."},{"pos":"PHRASE 短语","cn":"为了好玩","en":"If you do something for fun or for the fun of it, you do it in order to enjoy yourself rather than because it is important or necessary.","ex":{"en":"I took my M. A. just for fun really","cn":"我拿文科硕士学位其实就是觉得好玩儿。"}},{"pos":"PHRASE 短语","cn":"(尤指不负责任的)玩笑，嬉闹，恶作剧","en":"You can refer to playful behaviour as fun and games, especially if you disapprove of it because you think it is irresponsible.","ex":{"en":"Police suspected that the boys, whose fun and games hurt a lot of people, were on drugs.","cn":"警察怀疑这些经常胡为瞎闹令不少人受害的男孩子在吸毒。"}},{"pos":"PHRASE 短语","cn":"开玩笑地;闹着玩地","en":"If you do something in fun, you do it as a joke or for amusement, without intending to cause any harm.","ex":{"en":"Don't say such things, even in fun.","cn":"不要说这些话，就算是开玩笑也不行。"}},{"pos":"PHRASE 短语","cn":"取笑;戏弄;拿…开玩笑","en":"If you make fun of someone or something or poke fun at them, you laugh at them, tease them, or make jokes about them in a way that causes them to seem ridiculous.","ex":{"en":"Don't make fun of me","cn":"不要取笑我。"}}]},"examples":[{"en":"Walking three miles in the pouring rain is not my idea of fun.","cn":"顶着倾盆大雨走三英里路，我可不认为是好玩的事。"},{"en":"We didn't mean to hurt him. It was just a bit of fun.","cn":"我们并非有意要伤害他，只不过是开个玩笑罢了。"}]},"fulfilled":{"oxford":{"phon":"fʊlˈfɪld","pos":"adjective","senses":[{"en":"feeling happy and satisfied that you are doing something useful with your life","cn":"感到满足的；觉得满意的；满足的","ex":{"en":"He doesn't feel fulfilled in his present job.","cn":"目前的工作未能让他感到满足。"}}]},"media":{"uk":"media/uk/fulfilled__gb_1.mp3","us":"media/us/fulfilled__us_1.mp3"},"examples":[{"en":"He doesn't feel fulfilled in his present job.","cn":"目前的工作未能让他感到满足。"},{"en":"Adult education helps people achieve more fulfilled lives.","cn":"成人教育可以让人生活更加充实。"}],"base":"fulfil"},"further":{"media":{"uk":"media/uk/further__gb_1.mp3","us":"media/us/further__us_1.mp3"},"oxford":{"phon":"ˈfɜːðə(r)","pos":"adjective","senses":[{"en":"more; additional","cn":"更多的；更进一步的；附加的","ex":{"en":"Cook for a further 2 minutes.","cn":"再煮两分钟。"}},{"en":"at or to a greater distance","cn":"（空间距离）较远，更远","lab":"especially British English","ex":{"en":"We had walked a bit further than I had realized.","cn":"我们走得比我想象的要远一点。"},"pos":"adverb"},{"en":"a longer way in the past or the future","cn":"（过去或未来）较远，更久远","ex":{"en":"Think further back into your childhood.","cn":"再往前回想你的童年。"},"pos":"adverb"},{"en":"to a greater degree or extent","cn":"进一步；在更大程度上；在更大范围内","ex":{"en":"to develop/increase/enhance/improve something further","cn":"进一步发展／增加／提高／改进某事物"},"pos":"adverb"},{"en":"in addition to what has just been said","cn":"此外；而且","lab":"formal","ex":{"en":"Further, it is important to consider the cost of repairs.","cn":"此外，重要的是要考虑修理费用。"},"pos":"adverb"},{"en":"to help something to develop or be successful","cn":"促进；增进","ex":{"en":"They hoped the new venture would further the cause of cultural cooperation in Europe.","cn":"他们希望这个新项目将促进欧洲文化合作事业。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADV-COMPAR 副词比较级形式","cn":"进一步地;在更大程度上;在更大范围内","en":"Further means to a greater extent or degree.","ex":{"en":"Inflation is below 5% and set to fall further","cn":"通货膨胀率在 5%以下，而且还将进一步下降。"}},{"pos":"ADV-COMPAR 副词比较级形式","cn":"(发展中)进一步地，向前推进地","en":"If you go or get further with something, or take something further, you make some progress.","ex":{"en":"They lacked the scientific personnel to develop the technical apparatus much further.","cn":"他们缺少能够进一步研发这一技术装置的科研人员。"}},{"pos":"ADV-COMPAR 副词比较级形式","cn":"(讨论中)进一步地，更极端地，更彻底地","en":"If someone goes further in a discussion, they make a more extreme statement or deal with a point more thoroughly.","ex":{"en":"On February 7th the Post went further, claiming that Mr Wood had grabbed and kissed another 13 women","cn":"2 月 7 日的《邮报》走得更远，声称伍德先生还强行抓住亲吻过另外 13 名女性。"}},{"pos":"ADJ 形容词","cn":"更多的;附加的;另外的","en":"A further thing, number of things, or amount of something is an additional thing, number of things, or amount.","ex":{"en":"His speech provides further evidence of his increasingly authoritarian approach","cn":"他的讲话更加证明了他变得越来越独裁。"}},{"pos":"ADV-COMPAR 副词比较级形式","cn":"(距离上)更远地，再往前地","en":"Further means a greater distance than before or than something else.","ex":{"en":"Now we live further away from the city centre","cn":"现在我们住得离市中心更远了。"}},{"pos":"ADV-COMPAR 副词比较级形式","cn":"(时间上)更(早或晚)","en":"Further is used in expressions such as 'further back' and 'further ahead' to refer to a point in time that is earlier or later than the time you are talking about.","ex":{"en":"Looking still further ahead, by the end of the next century world population is expected to be about ten billion.","cn":"再往前看，到下个世纪末世界人口预计将达约 100 亿。"}},{"pos":"VERB 动词","cn":"促进;推进;增进","en":"If you further something, you help it to progress, to be successful, or to be achieved.","ex":{"en":"In return, they are themselves accused of furthering their own (leftist) political interests","cn":"作为回应，他们自己也被指责推动自己的(左翼)政治利益。"}},{"pos":"ADV 副词","cn":"而且;再者;此外","en":"You use further to introduce a statement that relates to the same general topic and that gives additional information or makes an additional point.","ex":{"en":"Dodd made no appeal of his death sentence and, further, instructed his attorney to sue anyone who succeeds in delaying his execution.","cn":"多德没有对自己的死刑判决提起上诉，而且他还要求自己的律师起诉任何成功使得这一死刑暂缓执行的人。"}},{"pos":"PREP-PHRASE 短语介词","cn":"(用于书信中)关于贵方信中所提/关于我们所谈到的","en":"Further to is used in letters in expressions such as 'further to your letter' or 'further to our conversation', in order to indicate what you are referring to in the letter.","ex":{"en":"Further to your letter, I agree that there are some presentational problems, politically speaking.","cn":"正如贵方信中所提到的，我也认为从政治角度来说，有一些词语表意上的问题。"}}]},"examples":[{"en":"My life is further complicated by having to work such long hours.","cn":"我得工作这么长的时间，因此生活中的麻烦事就更多了。"},{"en":"I am not satisfied with your explanation and intend to take the matter further.","cn":"我对你的解释不满意，打算进一步探讨这个问题。"}]},"fun-loving":{"oxford":{"phon":"ˈfʌn lʌvɪŋ","pos":"adjective","senses":[{"en":"liking to enjoy themselves","cn":"喜欢玩乐的"}]},"media":{"uk":"media/uk/fun_loving_1_gb_1.mp3","us":"media/us/fun_loving_1_us_1.mp3"}},"furthermore":{"media":{"uk":"media/uk/furthermore__gb_1.mp3","us":"media/us/furthermore__us_1.mp3"},"oxford":{"phon":"ˌfɜːðəˈmɔː(r)","pos":"adverb","senses":[{"en":"in addition to what has just been stated. Furthermore is used especially to add a point to an argument.","cn":"此外；而且；再者","ex":{"en":"He said he had not discussed the matter with her. Furthermore, he had not even contacted her.","cn":"他说他没有和她讨论过这个问题。而且，甚至没有和她联系过。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"而且;此外;再者","en":"Furthermore is used to introduce a piece of information or opinion that adds to or supports the previous one.","ex":{"en":"Furthermore, they claim that any such interference is completely ineffective.","cn":"此外，他们还声称任何这样的干预都是完全无效的。"}}]},"examples":[{"en":"He said he had not discussed the matter with her. Furthermore, he had not even contacted her.","cn":"他说他没有和她讨论过这个问题。而且，甚至没有和她联系过。"},{"en":"He is old and unpopular. Furthermore, he has at best only two years of political life ahead of him.","cn":"他年纪已老﹐又不得人心﹐而且他最多也只有两年的政治生命了。"}]},"function":{"media":{"uk":"media/uk/function__gb_1.mp3","us":"media/us/function__us_1.mp3"},"oxford":{"phon":"ˈfʌŋkʃn","pos":"noun","senses":[{"en":"a special activity or purpose of a person or thing","cn":"作用；功能；职能；机能","g":"[countable, uncountable]","ex":{"en":"The club serves a useful function as a meeting place.","cn":"这家俱乐部具有实用功能，可以用作会场。"}},{"en":"a social event or official ceremony","cn":"社交聚会；典礼；宴会","g":"[countable]","ex":{"en":"The hall provided a venue for weddings and other functions.","cn":"大厅可以举办婚礼和其他公开活动。"}},{"en":"a quantity whose value depends on the varying values of others. In the statement 2x=y, y is a function of x.","cn":"函数","g":"[countable]","lab":"mathematics","ex":{"en":"Salary is a function of age and experience.","cn":"工资视年龄和经验而定。"}},{"en":"a part of a program, etc. that performs a basic operation","cn":"子程序；子例程","g":"[countable]","lab":"computing"},{"en":"to work in the correct way","cn":"起作用；正常工作；运转","lab":"humorous","ex":{"en":"We now have a functioning shower.","cn":"现在我们有一个功能正常的淋浴器。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"功能;作用;职责","en":"The function of something or someone is the useful thing that they do or are intended to do.","ex":{"en":"The main function of the merchant banks is to raise capital for industry.","cn":"商业银行的主要职能是为产业融资。"}},{"pos":"VERB 动词","cn":"工作;运转;运行","en":"If a machine or system is functioning, it is working or operating.","ex":{"en":"The authorities say the prison is now functioning normally","cn":"当局称监狱现在运转正常。"}},{"pos":"VERB 动词","cn":"发挥功能;起作用;行使职责","en":"If someone or something functions as a particular thing, they do the work or fulfil the purpose of that thing.","ex":{"en":"On weekdays, one third of the room functions as workspace.","cn":"在工作日，房间的1/3用作办公区域。"}},{"pos":"N-COUNT 可数名词","cn":"(计算机的)功能(指执行的一系列操作)","en":"A function is a series of operations that a computer performs, for example when a single key or a combination of keys is pressed."},{"pos":"N-COUNT 可数名词","cn":"应变量;随他物变化而变化的事物","en":"If you say that one thing is a function of another, you mean that its amount or nature depends on the other thing.","ex":{"en":"Investment is a function of the interest rate.","cn":"投资随着利率的变化而变。"}},{"pos":"N-COUNT 可数名词","cn":"(正式的)宴会，大型聚会","en":"A function is a large formal dinner or party."}]},"examples":[{"en":"Many children can't function effectively in large classes.","cn":"许多孩子在大伙儿上课时学习效果不好。"},{"en":"This design aims for harmony of form and function.","cn":"这个设计旨在使形式和功能协调一致。"}]},"fund-raising":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"筹款;募捐","en":"Fund-raising is the activity of collecting money to support a charity or political campaign or organization.","ex":{"en":"Encourage her to get involved in fund-raising for charity.","cn":"鼓励她参加慈善募捐活动。"}}]},"media":{"uk":"media/uk/fund_raising_1_gb_1.mp3","us":"media/us/fund_raising_1_us_1.mp3"}},"furry":{"media":{"uk":"media/uk/furry__gb_1.mp3","us":"media/us/furry__us_1.mp3"},"oxford":{"phon":"ˈfɜːri","pos":"adjective","senses":[{"en":"covered with fur","cn":"覆盖毛皮的","ex":{"en":"small furry animals","cn":"毛茸茸的小动物"}},{"en":"like fur","cn":"毛皮似的；毛一般的","ex":{"en":"The moss was soft and furry to the touch.","cn":"苔藓柔软，摸起来像绒毛。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(动物)毛皮覆盖的，毛茸茸的","en":"A furry animal is covered with thick, soft hair.","ex":{"en":"...the coyote's furry tail.","cn":"郊狼毛茸茸的尾巴"}},{"pos":"ADJ 形容词","cn":"毛皮般柔软的","en":"If you describe something as furry, you mean that it has a soft rough texture like fur.","ex":{"en":"...his herringbone tweed coat with its furry lining.","cn":"他那件带毛绒衬里的人字纹粗花呢外套"}},{"pos":"ADJ 形容词","cn":"(通常指因生病而)长(舌)苔的","en":"If you have a furry tongue, your tongue is covered with a layer of a soft greyish-white substance, usually because you are unwell."}]},"examples":[{"en":"The moss was soft and furry to the touch.","cn":"苔藓柔软，摸起来像绒毛。"},{"en":"small furry animals","cn":"毛茸茸的小动物"}]},"funding":{"media":{"uk":"media/uk/funding__gb_1.mp3","us":"media/us/funding__us_1.mp3"},"oxford":{"phon":"ˈfʌndɪŋ","pos":"noun","senses":[{"en":"money for a particular purpose; the act of providing money for such a purpose","cn":"（专项）基金；提供资金","ex":{"en":"federal/state funding","cn":"联邦／州出资"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(政府或机构提供的)资金，款项，拨款","en":"Funding is money which a government or organization provides for a particular purpose.","ex":{"en":"They hope for government funding for the scheme","cn":"他们希望政府为这个计划提供资金。"}}]},"examples":[{"en":"There have been large cuts in government funding for scientific research.","cn":"政府提供的科研资金已大幅度削减。"},{"en":"College directors have called for more government funding.","cn":"学院董事呼吁增加政府拨款。"}],"base":"fund"},"furthest":{"collins":{"senses":[{"pos":"ADV-SUPERL 副词最高级形式","cn":"在最大程度上;在最大范围内;最大限度地","en":"Furthest means to a greater extent or degree than ever before or than anything or anyone else.","ex":{"en":"The south of England, where prices have fallen furthest, will remain the weakest market","cn":"价格下跌得最厉害的英格兰南部仍将是最疲软的市场。"}},{"pos":"ADV-SUPERL 副词最高级形式","cn":"(距离上)最远地，最往前","en":"Furthest means at a greater distance from a particular point than anyone or anything else, or for a greater distance than anyone or anything else.","ex":{"en":"The risk of thunder is greatest in those areas furthest from the coast","cn":"距离海岸最远的那些地区受雷击的危险最大。"}}]},"media":{"uk":"media/uk/furthest__gb_1.mp3","us":"media/us/furthest__us_1.mp3"},"examples":[{"en":"There was a huge tapestry on the furthest wall.","cn":"最远的那面墙上有一张巨大的挂毯。"},{"en":"He walked slowly toward the end of the jury box furthest from the judge.","cn":"他慢慢地向陪审团席离法官最远的那头走去。"}],"oxford":{"phon":"ˈfɜːðɪst","pos":"adverb","senses":[{"en":"at or to the greatest distance in space or time","cn":"（空间或时间上）最远，最久","ex":{"en":"a competition to see who could throw (the) furthest","cn":"一场比赛，看谁能扔得最远"}},{"en":"at the greatest distance in space or time","cn":"（空间或时间上）最远的，最久的","ex":{"en":"the furthest point of the journey","cn":"旅程的最远点"},"pos":"adjective"}]}},"full-grown":{"oxford":{"phon":"ˌfʊl ˈɡrəʊn","pos":"adjective","senses":[{"en":"having reached the greatest size to which they can grow and stopped growing","cn":"长足了的；长成的；成熟的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(动物或植物)发育完全的，完全长成的，成熟的","en":"An animal or plant that is full-grown has reached its full adult size and stopped growing.","ex":{"en":"...a full-grown male orang-utan.","cn":"成年的雄性猩猩"}}]},"media":{"uk":"media/uk/full_grown_1_gb_1.mp3","us":"media/us/full_grown_1_us_1.mp3"},"examples":[{"en":"A full-grown elephant may weigh 2,000 pounds.","cn":"成年大象的体重可达2,000磅。"}]},"furiously":{"oxford":{"phon":"ˈfjʊəriəsli","pos":"adverb","senses":[{"en":"in an extremely angry way","cn":"愤怒地","ex":{"en":"‘Damn!’ he said furiously.","cn":"“该死！”他愤怒地说。"}},{"en":"with great energy, speed or anger","cn":"激烈的；猛烈的；高速的；盛怒的","ex":{"en":"They worked furiously all weekend, trying to get it finished on time.","cn":"他们整个周末都在埋头苦干，力争按时完成工作。"}}]},"media":{"uk":"media/uk/furiously__gb_1.mp3","us":"media/us/furiously__us_1.mp3"},"examples":[{"en":"They worked furiously all weekend, trying to get it finished on time.","cn":"整个周末他们拼命工作，以求按时完成这项任务。"},{"en":"‘Damn!’ he said furiously.","cn":""}]},"full-scale":{"oxford":{"phon":"ˌfʊl ˈskeɪl","pos":"adjective","senses":[{"en":"that is as complete and careful as possible","cn":"全面的；完全的；彻底的","ex":{"en":"a full-scale attack","cn":"全面攻击"}},{"en":"that is the same size as something that is being copied","cn":"原尺寸的；和实物同样大小的","ex":{"en":"a full-scale model","cn":"原尺寸模型"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"完全的;彻底的;最大限度的","en":"Full-scale means as complete, intense, or great in extent as possible.","ex":{"en":"...the possibility of a full-scale nuclear war.","cn":"爆发全面核战争的可能性"}},{"pos":"ADJ 形容词","cn":"与实物一样大小的;原尺寸的","en":"A full-scale drawing or model is the same size as the thing that it represents.","ex":{"en":"...working, full-scale prototypes.","cn":"能够工作的原尺寸样机"}}]},"media":{"uk":"media/uk/full_scale_1_gb_1.mp3","us":"media/us/full_scale_1_us_1.mp3"},"examples":[{"en":"a full-scale model","cn":"原尺寸模型"},{"en":"a full-scale attack","cn":"全面攻击"}]},"fuels":{"lemma":"fuel","media":{"uk":"media/uk/fuel__gb_1.mp3","us":"media/us/fuel__us_1.mp3"}},"full-time":{"oxford":{"phon":"ˌfʊl ˈtaɪm","pos":"noun","senses":[{"en":"the end of a sports game","cn":"（体育运动的）全场比赛结束时间，终场","ex":{"en":"The referee blew his whistle for full time.","cn":"裁判吹响了比赛结束的哨音。"}},{"en":"for all the hours of a week during which people normally work or study, rather than just for a part of it","cn":"全日（制）；全职的（地）；全日的（地）","ex":{"en":"students in full-time education","cn":"全日制学生"},"pos":"adjective, adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"全职的;专职的;全日制的","en":"Full-time work or study involves working or studying for the whole of each normal working week rather than for part of it.","ex":{"en":"...a full-time job.","cn":"全职工作"}},{"pos":"PHRASE 短语","cn":"费时费力的活","en":"If you describe a regular activity or task as a full-time job, you mean that it takes up so much of your time it is like doing a paid job.","ex":{"en":"The way she did it, mothering was a full-time job.","cn":"照顾孩子于她是一件不得空闲的苦差事。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(足球等的)比赛结束，终场","en":"In games such as football, full-time is the end of a match.","ex":{"en":"The score at full-time was Arsenal 1, Sampdoria 1.","cn":"比赛结束时阿森纳队和桑普多利亚队 1 比 1 战平。"}}]},"media":{"uk":"media/uk/full_time_1_gb_1.mp3","us":"media/us/full_time_1_us_1.mp3"},"examples":[{"en":"She works full-time and still manages to run a home.","cn":"她做全职工作，仍能照管好家庭。"},{"en":"Looking after a child is a full-time job (= hard work that takes a lot of time).","cn":"照管小孩是一天忙到晚的活儿。"}]},"fundamental":{"media":{"uk":"media/uk/fundamental__gb_1.mp3","us":"media/us/fundamental__us_1.mp3"},"oxford":{"phon":"ˌfʌndəˈmentl","pos":"adjective","senses":[{"en":"serious and very important; affecting the most central and important parts of something","cn":"十分重大的；根本的","ex":{"en":"the fundamental principles of scientific method","cn":"科学方法的基本原则"}},{"en":"central; forming the necessary basis of something","cn":"基础的；基本的","ex":{"en":"Hard work is fundamental to success.","cn":"勤奋工作是成功的基础。"}},{"en":"forming the source or base from which everything else is made; not able to be divided any further","cn":"基本的；不能再分的","g":"[only before noun]","lab":"physics","ex":{"en":"a fundamental particle","cn":"基本粒子"}},{"en":"a basic rule or principle; an essential part","cn":"基本规律；根本法则；基本原理；基础","ex":{"en":"the fundamentals of modern physics","cn":"现代物理学的基本原理"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"基本的;根本的;主要的;基础的","en":"You use fundamental to describe things, activities, and principles that are very important or essential. They affect the basic nature of other things or are the most important element upon which other things depend.","ex":{"en":"Our constitution embodies all the fundamental principles of democracy","cn":"我们的宪法体现了民主的所有基本原则。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"根本性的;固有的;根深蒂固的","en":"You use fundamental to describe something which exists at a deep and basic level, and is therefore likely to continue.","ex":{"en":"But on this question, the two leaders have very fundamental differences","cn":"但在这个问题上，两位领导人有着根本性的分歧。"}},{"pos":"ADJ 形容词","cn":"必需的;不可或缺的","en":"If one thing is fundamental to another, it is absolutely necessary to it, and the second thing cannot exist, succeed, or be imagined without it.","ex":{"en":"He believes better relations with China are fundamental to the well-being of the area","cn":"他相信和中国建立更加良好的关系对这一地区的繁荣发展至关重要。"}},{"pos":"ADJ 形容词","cn":"最根本的;最重要的","en":"You can use fundamental to show that you are referring to what you consider to be the most important aspect of a situation, and that you are not concerned with less important details.","ex":{"en":"The fundamental problem lies in their inability to distinguish between reality and invention","cn":"最根本的问题在于他们无法分清现实和虚构。"}},{"pos":"ADJ 形容词","cn":"(研究)基础性的","en":"Fundamental research into a subject is concerned with gaining knowledge about the subject itself, rather than its practical aspects.","ex":{"en":"Industry leaders want scientists to engage in fundamental research, not applied research.","cn":"行业领袖希望科学家从事基础性研究，而非应用性研究。"}}]},"examples":[{"en":"A fundamental change in the organization of health services was required.","cn":"公共医疗在组织上需要一个根本性的变革。"},{"en":"He taught me the fundamentals of the job.","cn":"他教给了我这工作的基本知识。"}]},"fully":{"media":{"uk":"media/uk/fully__gb_1.mp3","us":"media/us/fully__us_1.mp3"},"oxford":{"phon":"ˈfʊli","pos":"adverb","senses":[{"en":"completely","cn":"完全地；全部地；充分地","ex":{"en":"I fully understand your motives.","cn":"我完全理解你的动机。"}},{"en":"the whole of; as much as","cn":"整整；足足","lab":"formal","ex":{"en":"The disease affects fully 30 per cent of the population.","cn":"这种病感染了足足 30% 的人口。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"完全地;最大程度地","en":"Fully means to the greatest degree or extent possible.","ex":{"en":"She was fully aware of my thoughts","cn":"她完全清楚我的想法。"}},{"pos":"ADV 副词","cn":"完全(结束)地","en":"You use fully to say that a process is completely finished.","ex":{"en":"He had still not fully recovered.","cn":"他还没有完全康复。"}},{"pos":"ADV-GRADED 副词","cn":"全面地;充分地;彻底地","en":"If you describe, answer, or deal with something fully, you leave out nothing that should be mentioned or dealt with.","ex":{"en":"Fiers promised to testify fully and truthfully","cn":"菲耶尔承诺所作证词将毫无保留且句句属实。"}},{"pos":"ADV 副词","cn":"(用于强调数量)整整，足足，至少","en":"Fully is used to emphasize how great an amount is.","ex":{"en":"Fully 30% of the poor could not even afford access to illegal shanties.","cn":"足足有 30%的贫困人口甚至连非法窝棚都住不起。"}}]},"examples":[{"en":"The disease affects fully 30 per cent of the population.","cn":"这种病感染了足足 30% 的人口。"},{"en":"She had fully recovered from the accident.","cn":"事故后她已经完全恢复过来。"}]},"full":{"media":{"uk":"media/uk/full__gb_1.mp3","us":"media/us/full__us_1.mp3"},"oxford":{"phon":"fʊl","pos":"adjective","senses":[{"en":"containing or holding as much or as many as possible; having no empty space","cn":"满的；充满的；满是…的","lab":"British English","sc":"with no empty space","ex":{"en":"a full bottle of wine","cn":"一满瓶葡萄酒"}},{"en":"having or containing a large number or amount of something/somebody","cn":"（有）大量的；（有）许多的；丰富的","sc":"having a lot","ex":{"en":"The sky was full of brightly coloured fireworks.","cn":"满天色彩绚丽的烟火。"}},{"en":"having had enough to eat","cn":"吃饱了的","lab":"British English also","sc":"with food","ex":{"en":"No more for me, thanks—I'm full up.","cn":"谢谢，我不要了，我已经饱了。"}},{"en":"complete; with nothing missing","cn":"完全的；完整的；详尽的","g":"[usually before noun]","sc":"complete","ex":{"en":"Full details are available on request.","cn":"详情备索。"}},{"en":"to the highest level or greatest amount possible","cn":"最高级的；尽量多的；最大量的","g":"[usually before noun]","sc":"as much as possible","ex":{"en":"Many people don't use their computers to their full potential.","cn":"很多人没有充分利用他们计算机的全部潜在功能。"}},{"en":"busy; involving a lot of activities","cn":"忙的；有很多活动的","sc":"busy","ex":{"en":"He'd had a very full life.","cn":"他度过了丰富多彩的一生。"}},{"en":"thinking or talking a lot about a particular thing","cn":"（关于某事物）想得很多，谈得很多","sc":"talking a lot","ex":{"en":"He was full of his new job and everything he'd been doing.","cn":"他滔滔不绝地谈他的新工作和所做的一切。"}},{"en":"used to emphasize an amount or a quantity","cn":"（强调数量）足足的，整整的","g":"[only before noun]","sc":"for emphasis","ex":{"en":"She is a full four inches shorter than her sister.","cn":"她比姐姐足足矮四英寸。"}},{"en":"appearing as a complete circle","cn":"圆的；满的","sc":"moon","ex":{"en":"The moon was full, the sky clear.","cn":"圆月碧空。"}},{"en":"large and round. ‘Full’ is sometimes used to avoid saying ‘fat’.","cn":"丰满的；圆鼓鼓的（有时用 full 以避免用 fat）","sc":"fat","ex":{"en":"He kissed her full sensual lips.","cn":"他吻了她那丰满性感的嘴唇。"}},{"en":"made with plenty of cloth; fitting loosely","cn":"宽松的；肥大的","sc":"clothes","ex":{"en":"a full skirt","cn":"宽裙"}},{"en":"deep, strong and rich","cn":"圆浑的；圆润的；浓郁的","sc":"tone/voice/flavour","ex":{"en":"He draws a unique full sound from the instrument.","cn":"他用乐器奏出了独特圆浑的音调。"}},{"en":"directly","cn":"直接地；径直地","ex":{"en":"She looked him full in the face.","cn":"她径直望着他的脸。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"满的;装满的","en":"If something is full, it contains as much of a substance or as many objects as it can.","ex":{"en":"Once the container is full, it stays shut until you turn it clockwise.","cn":"容器一旦装满它会保持关闭，想要打开须按顺时针方向转动。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有大量…的;满是…的","en":"If a place or thing is full of things or people, it contains a large number of them.","ex":{"en":"The case was full of clothes","cn":"箱子里塞满了衣服。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"充满(某一情感或特质)的","en":"If someone or something is full of a particular feeling or quality, they have a lot of it.","ex":{"en":"I feel full of confidence and so open to possibilities","cn":"我感到信心十足，愿意考虑各种可能。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"满员的;没有空位(或空间)的","en":"You say that a place or vehicle is full when there is no space left in it for any more people or things.","ex":{"en":"The main car park was full when I left about 10.45","cn":"我 10 点 45 分左右离开时，主停车场已经没有车位了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(手或胳膊)占着的，拿满了的，挂满了的","en":"If your hands or arms are full, you are carrying or holding as much as you can carry.","ex":{"en":"Sylvia entered, her arms full of packages","cn":"西尔维娅走了进来，怀里抱满了包裹。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"饱的;吃(或喝)胀的","en":"If you feel full, you have eaten or drunk so much that you do not want anything else.","ex":{"en":"It's healthy to eat when I'm hungry and to stop when I'm full.","cn":"饿了就吃，饱了就停，这样很健康。"}},{"pos":"ADJ 形容词","cn":"(置于名词前)所有的，全部的","en":"You use full before a noun to indicate that you are referring to all the details, things, or people that it can possibly include.","ex":{"en":"Full details will be sent to you once your application has been accepted","cn":"所有细节会在申请接受后马上寄出。"}},{"pos":"ADJ 形容词","cn":"(声音、光线、力气等)最大(强度)的","en":"Full is used to describe a sound, light, or physical force which is being produced with the greatest possible power or intensity.","ex":{"en":"From his study came the sound of Mahler, playing at full volume","cn":"从他的书房里传出马勒的乐曲，音量开到了最大。"}},{"pos":"ADJ 形容词","cn":"完全的;充分的;彻底的","en":"You use full to emphasize the completeness, intensity, or extent of something.","ex":{"en":"We should conserve oil and gas by making full use of other energy sources","cn":"我们应该通过充分利用其他能源来节省石油和天然气。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(内容)详尽的，丰富的","en":"A full statement or report contains a lot of information and detail.","ex":{"en":"Mr Primakov gave a full account of his meeting with the President.","cn":"普里马科夫先生详细叙述了他和总统的会面。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(生活)多姿多彩的，充实的","en":"If you say that someone has or leads a full life, you approve of the fact that they are always busy and do a lot of different things.","ex":{"en":"You will be successful in whatever you do and you will have a very full and interesting life.","cn":"你不管做什么都会成功，并且会过着非常充实有趣的生活。"}},{"pos":"ADV 副词","cn":"恰好;正好;直接地","en":"You use full to emphasize the force or directness with which someone or something is hit or looked at.","ex":{"en":"The burning liquid hit him full in the right eye","cn":"滚烫的液体正好溅进了他的右眼。"}},{"pos":"ADJ 形容词","cn":"(所拥有的权利、地位或重要性)完整的，正式的","en":"You use full to refer to something which gives you all the rights, status, or importance for a particular position or activity, rather than just some of them.","ex":{"en":"How did the meeting go, did you get your full membership?","cn":"面谈进行得怎么样，你成为正式成员了吗？"}},{"pos":"ADJ 形容词","cn":"(味道)浓烈的，浓郁的","en":"A full flavour is strong and rich.","ex":{"en":"Italian plum tomatoes have a full flavour, and are best for cooking.","cn":"意大利李形番茄味道很重，最适合烹饪。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(身体某一部位)丰满的，圆润的","en":"If you describe a part of someone's body as full, you mean that it is rounded and rather large.","ex":{"en":"The Juno Collection specialises in large sizes for ladies with a fuller figure.","cn":"朱诺系列专门针对身材较为丰满的女士推出大号女装。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(裙摆或袖子)宽大的，宽松的","en":"A full skirt or sleeve is wide and has been made from a lot of fabric.","ex":{"en":"My wedding dress has a very full skirt.","cn":"我结婚礼服的裙摆很宽松。"}},{"pos":"ADJ 形容词","cn":"(月)满的，圆的","en":"When there is a full moon, the moon appears as a bright, complete circle."},{"pos":"PHRASE 短语","cn":"所有地;全部地;全数地","en":"You say that something has been done or described in full when everything that was necessary has been done or described.","ex":{"en":"The medical experts have yet to report in full","cn":"医学专家尚未提出完整的报告。"}},{"pos":"PHRASE 短语","cn":"(尤指对令人不快的事)很清楚地知道(或了解)，一清二楚","en":"If you say that a person knows full well that something is true, especially something unpleasant, you are emphasizing that they are definitely aware of it, although they may behave as if they are not.","ex":{"en":"He knew full well he'd be ashamed of himself later.","cn":"他很清楚地知道自己过后会无地自容。"}},{"pos":"PHRASE 短语","cn":"尽量;在最大程度上;充分地;彻底地","en":"Something that is done or experienced to the full is done to as great an extent as is possible.","ex":{"en":"She probably has a good mind, which should be used to the full","cn":"她可能很有头脑，应该充分运用。"}},{"pos":"PHRASE 短语","cn":"洋洋得意;自以为是","en":"If you say to someone 'you're full of yourself', you disapprove of them because they appear very pleased with themselves, thinking that they are very clever, special, or important.","ex":{"en":"He's full of himself, sharp and aggressive and sometimes he comes over badly.","cn":"他是个自以为是的家伙，说话尖酸又爱挑衅，有时会给人留下极差的印象。"}},{"pos":"","cn":"","en":"to be full of beans→see: ;"},{"pos":"","cn":"","en":"full blast→see: ;"},{"pos":"","cn":"","en":". to come full circle→see: ;"},{"pos":"","cn":"","en":". to have your hands full→see: ;"},{"pos":"","cn":"","en":"in full swing→see: ;"}]},"examples":[{"en":"The kids still weren't full, so I gave them an ice cream each.","cn":"孩子们还没有吃饱，所以我给他们每人一份冰淇淋。"},{"en":"Many people don't use their computers to their full potential.","cn":"很多人没有充分利用他们计算机的全部潜在功能。"}]},"future":{"media":{"uk":"media/uk/future__gb_1.mp3","us":"media/us/future__us_1.mp3"},"oxford":{"phon":"ˈfjuːtʃə(r)","pos":"noun","senses":[{"en":"the time that will come after the present or the events that will happen then","cn":"将来；未来","g":"[singular]","ex":{"en":"We need to plan for the future.","cn":"我们需要为将来作好打算。"}},{"en":"what will happen to somebody/something at a later time","cn":"未来的事；将来发生的事；前景","g":"[countable]","ex":{"en":"The company faces a very uncertain future.","cn":"公司面临着非常不确定的未来。"}},{"en":"the possibility of being successful or surviving at a later time","cn":"前途；前程","g":"[singular, uncountable]","ex":{"en":"They have a bright future ahead of them.","cn":"他们的前途一片光明。"}},{"en":"goods or shares that are bought at agreed prices but that will be delivered and paid for at a later time","cn":"期货","g":"[plural]","lab":"finance","ex":{"en":"oil futures","cn":"石油期货"}},{"en":"the form of a verb that expresses what will happen after the present","cn":"将来时；将来式","g":"[singular]","lab":"grammar"},{"en":"taking place or existing at a time after the present","cn":"将来的；未来的；将来发生的","ex":{"en":"The land will remain untouched for future generations to enjoy.","cn":"这片土地将保持原样，供子孙后代享用。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"未来;将来;将来发生的事","en":"The future is the period of time that will come after the present, or the things that will happen then.","ex":{"en":"The spokesman said no decision on the proposal was likely in the immediate future","cn":"发言人说近期不会就这项提案作出决议。"}},{"pos":"ADJ 形容词","cn":"未来的;将来的","en":"Future things will happen or exist after the present time. for future reference→see: ;","ex":{"en":"She said if the world did not act conclusively now, it would only bequeath the problem to future generations","cn":"她说如果人类现在不采取决定性的行动，那就只会把问题留给子孙后代。"}},{"pos":"N-COUNT 可数名词","cn":"前途;前景","en":"Someone's future, or the future of something, is what will happen to them or what they will do after the present time.","ex":{"en":"His future as prime minister depends on the outcome of the elections","cn":"他能否继续坐在首相的位子上取决于选举的结果。"}},{"pos":"N-COUNT 可数名词","cn":"成功的可能;未来的希望","en":"If you say that someone or something has a future, you mean that they are likely to be successful or to survive.","ex":{"en":"These abandoned children have now got a future","cn":"这些被抛弃的孩子现在有了希望。"}},{"pos":"N-PLURAL 复数名词","cn":"期货","en":"When people trade in futures, they buy stocks and shares, commodities such as coffee or oil, or foreign currency at a price that is agreed at the time of purchase for items which are delivered some time in the future.","ex":{"en":"This report could spur some buying in corn futures when the market opens today","cn":"这一报告可能会在今天开市后刺激一些人买进玉米期货。"}},{"pos":"ADJ 形容词","cn":"(语法中)将来(时)的","en":"In grammar, the future tense of a verb is the one used to talk about things that are going to happen. In English, this applies to verb groups consisting of 'will' or 'shall' and the base form of a verb. The future perfect tense of a verb is used to talk about things that will have happened at some time in the future."},{"pos":"PHRASE 短语","cn":"今后，从今以后(有时亦作 in the future，尤用于美国英语中)","en":"You use in future when saying what will happen from now on, which will be different from what has previously happened. The form in the future is sometimes used instead, especially in American English.","ex":{"en":"In future the President will be chosen by the people instead of by the National Assembly","cn":"今后总统将由人民选举产生，而非国民议会选出。"}},{"pos":"PHRASE 短语","cn":"未来将发生…;将来会发生…","en":"If you wonder what the future holds, you wonder what will happen in the future.","ex":{"en":"We wondered what the future would hold for our baby son.","cn":"我们不知道宝贝儿子长大了会怎样。"}},{"pos":"PHRASE 短语","cn":"未来在(于…)","en":"If you say that someone's future lies in a particular place or activity, you think they will be most successful or happy in that place or doing that activity.","ex":{"en":"Armstrong is uncertain where his long-term future lies","cn":"阿姆斯特朗拿不准自己的人生远景在何方。"}}]},"examples":[{"en":"This deal could safeguard the futures of the 2 000 employees.","cn":"这个协议可以保障 2 000 名雇员今后的生活。"},{"en":"I can't see any future in this relationship.","cn":"我看不出这个关系会有什么前途。"}]},"furious":{"media":{"uk":"media/uk/furious__gb_1.mp3","us":"media/us/furious__us_1.mp3"},"oxford":{"phon":"ˈfjʊəriəs","pos":"adjective","senses":[{"en":"very angry","cn":"狂怒的；暴怒的","ex":{"en":"Their incompetence made me furious.","cn":"他们的无能令我大为光火。"}},{"en":"with great energy, speed or anger","cn":"激烈的；猛烈的；高速的；盛怒的","ex":{"en":"a furious debate","cn":"激烈的辩论"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"狂怒的;暴怒的","en":"Someone who is furious is extremely angry.","ex":{"en":"He is furious at the way his wife has been treated","cn":"妻子受到的待遇让他感到异常愤怒。"}},{"pos":"ADJ 形容词","cn":"大力的;猛烈的;激烈的","en":"Furious is also used to describe something that is done with great energy, effort, speed, or violence.","ex":{"en":"A furious gunbattle ensued.","cn":"一场激烈的枪战随之爆发。"}}]},"examples":[{"en":"He was furious with himself for letting things get so out of control.","cn":"他对自己很恼火，怪自己竟让事情变得如此不可收拾。"},{"en":"They worked furiously all weekend, trying to get it finished on time.","cn":"整个周末他们拼命工作，以求按时完成这项任务。"}]},"fur":{"oxford":{"phon":"fɜː(r)","pos":"noun","senses":[{"en":"the soft thick mass of hair that grows on the body of some animals","cn":"（动物浓厚的）软毛","g":"[uncountable]","ex":{"en":"The cat carefully licked its fur.","cn":"那只猫仔细地舔自己的毛。"}},{"en":"the skin of an animal with the fur still on it, used especially for making clothes","cn":"（动物的）毛皮","g":"[uncountable]","ex":{"en":"a fur coat","cn":"毛皮大衣"}},{"en":"an artificial material that looks and feels like fur","cn":"人造毛皮","g":"[uncountable]"},{"en":"a piece of clothing, especially a coat or jacket, made of real or artificial fur","cn":"毛皮衣服，裘皮衣服（尤指大衣或短上衣）","g":"[countable]","ex":{"en":"elegant ladies in furs","cn":"穿着裘皮衣服的高雅贵妇"}},{"en":"a hard grey-white substance that is sometimes left inside water pipes and containers for heating water","cn":"水垢，水碱","g":"[uncountable]","lab":"British English"},{"en":"a grey-white layer that forms on a person’s tongue, especially when they are ill","cn":"舌苔","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"(哺乳动物的)软毛","en":"Fur is the thick and usually soft hair that grows on the bodies of many mammals.","ex":{"en":"This creature's fur is short, dense and silky.","cn":"这种动物的毛又短又密、丝般柔滑。"}},{"pos":"N-VAR 可变名词","cn":"(用于制衣等的)毛皮，皮草","en":"Fur is the fur-covered skin of an animal that is used to make clothing or small carpets.","ex":{"en":"She had on a black coat with a fur collar","cn":"她穿着一件毛皮领子的黑色外套。"}},{"pos":"N-COUNT 可数名词","cn":"毛皮大衣;毛皮围脖","en":"A fur is a coat made from real or artificial fur, or a piece of fur worn round your neck.","ex":{"en":"There were women in furs and men in comfortable overcoats.","cn":"女人们穿着毛皮大衣，男人们穿着舒适的外套。"}},{"pos":"N-MASS 物质名词","cn":"仿毛皮","en":"Fur is an artificial fabric that looks like fur and is used, for example, to make clothing, soft toys, and seat covers."},{"pos":"PHRASE 短语","cn":"引起激烈争吵(或争论)","en":"If an event sets the fur flying, it causes a great argument.","ex":{"en":"Last week's meeting of the 1922 Committee set the fur flying again on the Tory backbenches","cn":"1922 年委员会上个星期的会议又一次引发了保守党后座议员激烈的争吵。"}},{"pos":"PHRASAL VERB-ERG","cn":"(使)(血管)堵塞","en":"If your veins or arteries fur up or are furred up, they become blocked, so that your blood cannot flow properly.","ex":{"en":"Three of my veins had furred up and I needed a triple bypass","cn":"我有三条静脉出现了堵塞，需要做个三支搭桥手术。"}},{"pos":"","cn":"","en":"相关词组：fur up"}]},"media":{"uk":"media/uk/fur__gb_1.mp3","us":"media/us/fur__us_1.mp3","img":["media/ldoce/img/fur.jpg"]},"examples":[{"en":"The animal is hunted for its fur.","cn":"狩猎这种动物是为了获取其毛皮。"},{"en":"a fur farm (= where animals are bred and killed for their fur)","cn":"毛皮动物饲养场"}]},"functions":{"lemma":"function"},"fuller":{"lemma":"full"},"furled":{"oxford":{"phon":"fɜːl","pos":"verb","senses":[{"en":"to roll and fasten sth such as a sail, a flag or an umbrella","cn":"卷起，收拢（帆、旗或伞）"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41furled.mp3","us":"media/ldoce/hwd/ame/c/ld41furled.mp3"},"examples":[{"en":"He held a furled umbrella in one hand.","cn":"他一只手里拿着一把收拢的雨伞。"}]},"funnier":{"lemma":"funny"},"fulfill":{"lemma":"fulfil"},"funds":{"lemma":"fund"},"fundamentals":{"lemma":"fundamental","media":{"uk":"media/ldoce/hwd/bre/1/brelasdefundamentals.mp3","us":"media/ldoce/hwd/ame/2/amelasdefundamentals.mp3"}},"fulfil":{"collins":{"senses":[{"pos":"VERB 动词","cn":"履行;实现;使应验","en":"If you fulfil something such as a promise, dream, or hope, you do what you said or hoped you would do.","ex":{"en":"President Kaunda fulfilled his promise of announcing a date for the referendum.","cn":"卡翁达总统兑现了他的承诺，宣布了全民公决的日期。"}},{"pos":"VERB 动词","cn":"实行;执行;完成","en":"To fulfil a task, role, or requirement means to do or be what is required, necessary, or expected.","ex":{"en":"Without them you will not be able to fulfil the tasks you have before you","cn":"没有他们你将无法完成面临的任务。"}},{"pos":"VERB 动词","cn":"满足;使满意;使有成就感","en":"If something fulfils you, or if you fulfil yourself, you feel happy and satisfied with what you are doing or with what you have achieved.","ex":{"en":"The war was the biggest thing in her life and nothing after that quite fulfilled her","cn":"这场战争是她生命中最重大的事件，从那以后再没有什么让她特别有成就感的了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do or provide what you promised, especially in politics or business when people are uncertain whether you can do this","cn":""},{"en":"to do what you have promised to do or what you must do, especially in politics or business","cn":""},{"en":"to faithfully keep an earlier promise or agreement although there may now be reasons for not keeping it","cn":""}]},"collocations":{"phrases":["ADV. amply, really He amply fulfilled the weight of expectation that they had placed on him. | completely | not quite Turkey is a market tha","VERB + FULFIL be able/unable to, can/could Alan was finally able to fulfil his promise to Sarah. | must Students must fulfil the following e"]},"media":{"uk":"media/ldoce/hwd/bre/b/fulfil0205.mp3","us":"media/ldoce/hwd/ame/a/laadfulfill.mp3"},"examples":[{"en":"Nursery schools should fulfil the function of preparing children for school.","cn":"幼儿园应该起到为儿童进小学作准备的作用。"},{"en":"No candidate fulfils all the criteria for this position.","cn":"没有候选人完全符合这个职位要求的标准。"}],"oxford":{"phon":"fʊlˈfɪl","pos":"verb","senses":[{"en":"to do or achieve what was hoped for or expected","cn":"实现","ex":{"en":"to fulfil your dream/ambition/potential","cn":"实现梦想／抱负；发挥潜力"}},{"en":"to do or have what is required or necessary","cn":"履行；执行；符合；具备","lab":"formal","ex":{"en":"to fulfil a duty/an obligation/a promise","cn":"履行职责／义务／诺言"}},{"en":"to have a particular role or purpose","cn":"起…作用；目的是","ex":{"en":"Nursery schools should fulfil the function of preparing children for school.","cn":"幼儿园应该起到为儿童进小学作准备的作用。"}},{"en":"to make somebody feel happy and satisfied with what they are doing or have done","cn":"使有成就感；使满足","ex":{"en":"I need a job that really fulfils me.","cn":"我需要一份真正令我感到满足的工作。"}},{"en":"to pack and send something that a customer has ordered","cn":"打包寄出（客户订购的货品）；完成（订单）","ex":{"en":"We aim to fulfil all orders within seven days.","cn":"我们力求七天内完成所有订单。"}}]}},"furore":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"狂怒;狂热;骚动","en":"A furore is a very angry or excited reaction by people to something.","ex":{"en":"The disclosure has already caused a furore among MPs.","cn":"对此事的揭露已经在议员中引起了骚动。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a furious argument, discussion, disagreement etc is one in which people express very angry feelings","cn":""},{"en":"something such as a discussion or relationship that is stormy is one in which angry feelings are often expressed","cn":""},{"en":"angry and excited","cn":""}]},"collocations":{"phrases":["ADJ. considerable | public | political","VERB + FURORE cause, create, provoke His choice of words created quite a furore.","FURORE + VERB surround sth the furore which surrounded her appointment as chairman | follow, result from sth | die down","PREP. amid a/the ~ (of) His resignation passed almost unnoticed amid the furore of the elections. | ~ about/over/surrounding the furore over"]},"media":{"uk":"media/ldoce/hwd/bre/8/furore_las3_br.mp3","us":"media/ldoce/hwd/ame/c/furor.mp3"},"examples":[{"en":"His novel about Jesus caused a furore among Christians.","cn":"他关于耶稣的小说激起了基督教徒的公愤。"},{"en":"the recent furore over the tax increases","cn":"近来因增税引起的骚动"}],"oxford":{"phon":"fjuˈrɔːri","pos":"noun","senses":[{"en":"great anger or excitement shown by a number of people, usually caused by a public event","cn":"群情激愤；骚动；轰动","ex":{"en":"Her choice of words created quite a furore.","cn":"她的措辞引起了轩然大波。"}}]}},"fulfilment":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"满足感;成就感","en":"Fulfilment is a feeling of satisfaction that you get from doing or achieving something, especially something useful.","ex":{"en":"...professional fulfilment.","cn":"职业满足感"}},{"pos":"N-UNCOUNT 不可数名词","cn":"履行;实现;完成;满足","en":"The fulfilment of a promise, threat, request, hope, or duty is the event or act of it happening or being made to happen.","ex":{"en":"Visiting Angkor was the fulfilment of a childhood dream.","cn":"游览吴哥实现了孩提时的一个梦想。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a feeling of happiness or pleasure, especially because you have achieved something good or useful","cn":""},{"en":"a feeling of pleasure and satisfaction that you get when you or someone connected with you has achieved something good","cn":""},{"en":"the feeling of being happy and satisfied because you have what you want or need. Contentment is rather a formal use","cn":""}]},"collocations":{"phrases":["ADJ. proper the proper fulfilment of their duties 2 feeling of satisfaction","ADJ. great She needed greater fulfilment in her job. | complete, perfect | partial | personal her search for personal fulfilment | intellect","VERB + FULFILMENT derive, find, gain, obtain | provide (sb with)","PREP. ~ from He derives a lot of fulfilment from his charity work. | ~ in I can't find fulfilment in doing housework.","PHRASES a desire/need for fulfilment, a sense of fulfilment They gain a sense of fulfilment from their work."]},"media":{"uk":"media/ldoce/hwd/bre/0/fulfilment0205.mp3","us":"media/ldoce/hwd/ame/b/laadfulfillment.mp3"},"examples":[{"en":"to find personal fulfilment","cn":"寻求个人的满足"},{"en":"the fulfilment of a dream","cn":"梦想的实现"}],"oxford":{"phon":"fʊlˈfɪlmənt","pos":"noun","senses":[{"en":"the act of doing or achieving what was hoped for or expected","cn":"做了或实现了所希望或期望的事情","ex":{"en":"the fulfilment of a dream","cn":"梦想的实现"}},{"en":"the fact of doing or having what is required or necessary","cn":"做了或有了所需的或必要","lab":"formal","ex":{"en":"the fulfilment of a promise","cn":"承诺的执行"}},{"en":"the feeling of being happy and satisfied with what you are doing or have done","cn":"满足：对自己正在做或已经做的事情感到高兴和满意的感觉","ex":{"en":"to find personal fulfilment","cn":"得到自我满足"}},{"en":"the act of packing and sending something that a customer has ordered","cn":"完成：包装和发送客户订购的物品的行为","ex":{"en":"The fulfilment of online orders remains a challenge for many retailers.","cn":"对于许多零售商来说，履行在线订单仍然是一个挑战。"}}]}},"futile":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无益的;无用的;徒劳的","en":"If you say that something is futile, you mean there is no point in doing it, usually because it has no chance of succeeding.","ex":{"en":"He brought his arm up in a futile attempt to ward off the blow","cn":"他扬起胳膊徒劳地想要挡住这一拳。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not likely to have a useful result","cn":""},{"en":"completely pointless because there is no chance at all of being successful","cn":""},{"en":"not useful or effective in any way","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When something fails to deliver a useful result, you can call it futile . Hopefully all the time you're spending studying vocabulary won't turn out to be futile !"}]},"collocations":{"phrases":["VERBS be, prove, seem | consider sth, describe sth as The president described these activities as futile.","ADV. absolutely, completely, quite, totally, utterly an utterly futile struggle for justice | largely, rather | apparently, seemingly | ulti"]},"media":{"uk":"media/ldoce/hwd/bre/6/futile0205.mp3","us":"media/ldoce/hwd/ame/0/futile.mp3"},"examples":[{"en":"Their efforts to revive him were futile.","cn":"他们努力使他苏醒，但失败了。"},{"en":"My appeal proved futile.","cn":"我的申诉白费了。"}],"oxford":{"phon":"ˈfjuːtaɪl","pos":"adjective","senses":[{"en":"having no purpose because there is no chance of success","cn":"徒然的；徒劳的；无效的","ex":{"en":"a futile attempt/exercise/gesture","cn":"徒然的尝试／练习／表示"}}]}},"fume":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"(难闻且常为有害的)烟,气体","en":"Fumes are the unpleasant and often unhealthy smoke and gases that are produced by fires or by things such as chemicals, fuel, or cooking.","ex":{"en":"...car exhaust fumes","cn":"汽车尾气"}},{"pos":"VERB 动词","cn":"发怒;生气","en":"If you fume over something, you express annoyance and anger about it.","ex":{"en":"He was still fuming over the remark","cn":"他还在为那句话生气。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be angry about something （","cn":"对…）生气"},{"en":"to give off smoke or gases","cn":"冒烟﹔冒气"}]},"vocab":{"pos":"1 n v 2 v 3 v","senses":[{"en":"To fume is to feel or express great anger. You would fume if your teacher accused you of cheating when you didn't."}]},"collocations":{"phrases":["ADV. inwardly, quietly","PREP. about/over She was still quietly fuming about Peter's remarks. | at We were all fuming at the delay.","PHRASES be left fuming Motorists were left fuming as police closed the motorway for six hours. | sit/stand (there) fuming He sat fuming over"]},"media":{"uk":"media/ldoce/hwd/bre/0/fume0205.mp3","us":"media/ldoce/hwd/ame/2/fume.mp3"},"examples":[{"en":"She sat in the car, silently fuming at the traffic jam.","cn":"她坐在汽车里，心中对交通堵塞感到十分恼火。"},{"en":"‘This is intolerable!’ she fumed. “","cn":"这真让人不可容忍！”她怒气冲冲地说。"}],"oxford":{"phon":"fjuːm","pos":"verb","senses":[{"en":"to be very angry about something","cn":"（对…）大为生气，十分恼火","g":"[intransitive, transitive]","ex":{"en":"She sat in the car, silently fuming at the traffic jam.","cn":"她坐在汽车里，心中对交通堵塞感到十分恼火。"}},{"en":"to produce smoke or fumes","cn":"冒烟；冒气","g":"[intransitive]"}]}},"fuss":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"紧张不安;大惊小怪;忙乱","en":"Fuss is anxious or excited behaviour which serves no useful purpose.","ex":{"en":"I don't know what all the fuss is about","cn":"我不知道为什么要这样大惊小怪的。"}},{"pos":"VERB 动词","cn":"紧张不安;大惊小怪;瞎忙活","en":"If you fuss, you worry or behave in a nervous, anxious way about unimportant matters or rush around doing unnecessary things.","ex":{"en":"Carol fussed about getting me a drink","cn":"卡萝尔手忙脚乱地要给我弄一杯喝的。"}},{"pos":"VERB 动词","cn":"(对…)关爱备至，过分体贴","en":"If you fuss over someone, you pay them a lot of attention and do things to make them happy or comfortable.","ex":{"en":"Auntie Hilda and Uncle Jack couldn't fuss over them enough.","cn":"希尔达姨妈和杰克姨父对他们宠爱有加。"}},{"pos":"PHRASE 短语","cn":"引起骚动;大吵大闹;大发牢骚","en":"If you make a fuss or kick up a fuss about something, you become angry or excited about it and complain.","ex":{"en":"I don't know why everybody makes such a fuss about a few mosquitoes","cn":"我不知道为什么大家对几只蚊子大惊小怪的。"}},{"pos":"PHRASE 短语","cn":"对…关爱备至;对…过分体贴","en":"If you make a fuss of someone, you pay them a lot of attention and do things to make them happy or comfortable.","ex":{"en":"When I arrived my nephews made a big fuss of me.","cn":"我到达的时候，侄子们围着我嘘寒问暖。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to keep complaining in an annoying way - use this about someone who complains all the time, even about things that are not important","cn":""},{"en":"to keep complaining in a bad-tempered way, especially when you think you have been treated unfairly","cn":""},{"en":"to complain angrily and noisily about something, so that everyone hears you or notices you","cn":""}]},"vocab":{"pos":"1 n 2 v","senses":[{"en":"If you are making a fuss , settle down! A fuss is a state of excitement, and it's usually about something not worth worrying or \"fussing\" about."}]},"collocations":{"phrases":["ADJ. awful, big, great, terrible","VERB + FUSS cause, kick up, make She kicked up an awful fuss when she heard about it.","FUSS + VERB blow over, die down Once the fuss has blown over, we'll be able to get on with work as usual.","PREP. without ~ They left quietly, without fuss. | ~ about She made a big fuss about not having a window seat on the plane. | ~ over I think","PHRASES make a fuss of sb The children were all making a great fuss of the new baby. | with the minimum of fuss The job was done with the mi"]},"media":{"uk":"media/ldoce/hwd/bre/7/fuss_n0205.mp3","us":"media/ldoce/hwd/ame/0/fuss1.mp3"},"examples":[{"en":"It's a very ordinary movie — I don't know what all the fuss is about (= why other people think it is so good).","cn":"这是部很普通的电影，我不懂为什么就轰动一时。"},{"en":"Steve kicks up a fuss every time I even suggest seeing you.","cn":"每次只要我提议看望你，史蒂夫就大吵大闹。"}],"oxford":{"phon":"fʌs","pos":"noun","senses":[{"en":"unnecessary excitement, worry or activity","cn":"无谓的激动（或忧虑、活动）；大惊小怪","g":"[uncountable, singular]","ex":{"en":"I hated all that fuss and bother.","cn":"我讨厌那些繁琐麻烦事。"}},{"en":"anger or complaints about something, especially something that is not important","cn":"（为小事）大吵大闹，大发牢骚","g":"[singular]","ex":{"en":"Steve kicks up a fuss every time I even suggest seeing you.","cn":"每次我即使只是提议看望你，史蒂夫就大吵大闹。"}},{"en":"to do things, or pay too much attention to things, that are not important or necessary","cn":"瞎忙一气；过分关心（枝节小事）","g":"[intransitive]","ex":{"en":"Stop fussing around and find something useful to do!","cn":"别瞎忙活了，找点有用的事干！"},"pos":"verb"},{"en":"to worry about things that are not very important","cn":"（为小事）烦恼，忧虑","g":"[intransitive]","ex":{"en":"Don't fuss, Mum, everything is all right.","cn":"别瞎操心了，妈妈，一切都好。"},"pos":"verb"}]}},"furnace":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"火炉;熔炉","en":"A furnace is a container or enclosed space in which a very hot fire is made, for example to melt metal, burn rubbish, or produce steam."},{"pos":"N-SING 单数名词","cn":"火炉般的地方;极闷热的地方","en":"If you say that a place is a furnace, you mean that it is very hot there.","ex":{"en":"How can we walk? It's a furnace out there.","cn":"我们怎么能走路呢？外面跟火炉似的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large container for a very hot fire, used to produce power, heat, or liquid metal","cn":"火炉﹐熔炉"},{"en":"a piece of equipment used to heat a building 〔","cn":"给建筑物供暖的〕锅炉"}]},"vocab":{"pos":"n","senses":[{"en":"A furnace is an appliance that heats houses and buildings by burning fuel or circulating hot water. Your furnace might rumble in the basement, sending heat up through your house's radiators."}]},"collocations":{"phrases":["ADJ. blazing, fiery, hot, red-hot | electric, gas | glass, steel | blast","VERB + FURNACE fire enough coal to fire the furnaces","FURNACE + VERB burn, glow The furnaces glowed fiercely. | roar A dark shed, lit only by the glow of roaring furnaces."]},"media":{"uk":"media/ldoce/hwd/bre/9/furnace_las3_br.mp3","us":"media/ldoce/hwd/ame/5/furnace.mp3"},"examples":[{"en":"It's like a furnace (= very hot) in here!","cn":"这里热得像火炉！"}],"oxford":{"phon":"ˈfɜːnɪs","pos":"noun","senses":[{"en":"a space surrounded on all sides by walls and a roof for heating metal or glass to very high temperatures","cn":"熔炉","ex":{"en":"It's like a furnace (= very hot) in here!","cn":"这里热得像火炉！"}},{"en":"a container in which water is heated to provide hot water and heating in a building or to produce steam in an engine","cn":"锅炉；汽锅","lab":"especially North American English"}]}},"fuzzy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(毛发)柔软卷曲的","en":"Fuzzy hair sticks up in a soft, curly mass.","ex":{"en":"He had fuzzy black hair and bright black eyes.","cn":"他一头柔软卷曲的黑发，眼睛又黑又亮。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"覆有细绒毛的;绒毛状的;毛茸茸的","en":"If something is fuzzy, it has a covering that feels soft and like fur.","ex":{"en":"...fuzzy material.","cn":"绒毛料子"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(图片、声音等)不清楚的，模糊的","en":"A fuzzy picture, image, or sound is unclear and hard to see or hear.","ex":{"en":"A couple of fuzzy pictures have been published.","cn":"有几张模糊的照片刊登了出来。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人或头脑)稀里糊涂的，迷迷糊糊的","en":"If you or your thoughts are fuzzy, you are confused and cannot think clearly.","ex":{"en":"He had little patience for fuzzy ideas.","cn":"他没什么耐心听那些糊里糊涂的想法。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不明确的;含混的","en":"You describe something as fuzzy when it is vague and not clearly defined.","ex":{"en":"The border between science fact and science fiction gets a bit fuzzy.","cn":"科学事实和科幻小说之间的界限变得有点儿模糊了。"}},{"pos":"ADJ 形容词","cn":"(计算机)模糊(逻辑)的","en":"Fuzzy logic is a type of computer logic that is supposed to imitate the way that humans think, for example by adapting to changing circumstances rather than always following the same procedure.","ex":{"en":"...domestic appliances that also use fuzzy logic to mimic the way a person would do the job manually.","cn":"同样使用模糊逻辑模拟手动操作的家用电器"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a picture, shape, image etc that is faint is unclear because it is a long way away, there is not enough light, or it was very lightly drawn","cn":""},{"en":"unclear so that only the general shape can be seen, and not small details","cn":""},{"en":"a photograph, television picture etc that is fuzzy is not clear, and it is difficult to see separate edges and objects, often because there is something wrong with your equipment or with the way the pictures were taken","cn":""}]},"collocations":{"phrases":["VERBS be, feel, look, seem, sound | become, go The screen suddenly went fuzzy.","ADV. all, extremely, very The truck's headlights were all fuzzy and ghostlike. | a bit, rather, slightly 2 sticking up","VERBS be | go","ADV. all My hair's gone all fuzzy! | a bit, rather"]},"media":{"uk":"media/ldoce/hwd/bre/5/fuzzy_las3_br.mp3","us":"media/ldoce/hwd/ame/7/fuzzy.mp3"},"examples":[{"en":"The soundtrack is fuzzy in places.","cn":"这电影声带有些地方模糊不清。"},{"en":"fuzzy ideas/thinking","cn":"糊涂的想法/思想"}],"oxford":{"phon":"ˈfʌzi","pos":"adjective","senses":[{"en":"covered with short soft fine hair or fur","cn":"覆有绒毛的；毛茸茸的","ex":{"en":"She stroked the baby's fuzzy head.","cn":"她抚摸着婴儿毛茸茸的脑袋。"}},{"en":"in a mass of tight curls","cn":"紧鬈的；拳曲的"},{"en":"not clear in shape or sound","cn":"（形状或声音）模糊不清的","ex":{"en":"a fuzzy image","cn":"模糊的形象"}},{"en":"confused and not expressed clearly","cn":"糊涂的；含混不清的","ex":{"en":"fuzzy ideas/thinking","cn":"糊涂的想法／思想"}}]}},"fugitive":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"逃亡者;亡命者;(通常指)逃犯","en":"A fugitive is someone who is running away or hiding, usually in order to avoid being caught by the police.","ex":{"en":"The rebel leader was a fugitive from justice.","cn":"叛军头目是一名在逃的不法之徒。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"use this to describe someone who has escaped , especially from a prison","cn":""},{"en":"someone who is on the loose or at large has escaped from the police or from a prison and is likely to be dangerous","cn":""},{"en":"someone who is on the run is trying to hide or escape from someone who is chasing them, especially the police","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"Someone who flees or runs away from the police to avoid capture is a fugitive . \"Authorities were looking for three men who escaped from prison today. Authorities believe the three fugitives may be disguised as nuns and advise the public to be careful.\""}]},"collocations":{"phrases":["ADJ. hunted, wanted one of the most wanted fugitives sought by the Italian police","PREP. ~ from a sanctuary where fugitives from justice could shelter"]},"media":{"uk":"media/ldoce/hwd/bre/1/fugitive_n0205.mp3","us":"media/ldoce/hwd/ame/d/fugitive.mp3"},"examples":[{"en":"a fugitive idea/thought","cn":"转瞬即逝的想法/思想"},{"en":"a fugitive from justice","cn":"逃犯"}],"oxford":{"phon":"ˈfjuːdʒətɪv","pos":"noun","senses":[{"en":"a person who has escaped or is running away from somewhere and is trying to avoid being caught","cn":"逃亡者；逃跑者；亡命者","ex":{"en":"a fugitive from justice","cn":"逃犯"}},{"en":"trying to avoid being caught","cn":"逃亡的；逃跑的","ex":{"en":"a fugitive criminal","cn":"逃犯"},"pos":"adjective"},{"en":"lasting only for a very short time","cn":"短暂的；易逝的","lab":"literary","ex":{"en":"a fugitive idea/thought","cn":"转瞬即逝的想法／思想"},"pos":"adjective"}]}},"futility":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"无益;无用;徒劳;白费","en":"Futility is a total lack of purpose or usefulness.","ex":{"en":"...the injustice and futility of terrorism.","cn":"恐怖主义的非正义性和枉费心机"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not likely to have a useful result","cn":""},{"en":"completely pointless because there is no chance at all of being successful","cn":""},{"en":"not useful or effective in any way","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When you can’t see the point in even trying, that’s the feeling of futility , the sense that no matter how much you work at it, nothing good will happen, so you might as well give up."}]},"collocations":{"phrases":["ADJ. complete, utter","VERB + FUTILITY know, realize, see, sense She could see the utter futility of trying to protest.","PHRASES a feeling/sense of futility"]},"media":{"uk":"media/ldoce/hwd/bre/6/futile0205.mp3","us":"media/ldoce/hwd/ame/0/futile.mp3"},"examples":[{"en":"the futility of war","cn":"战争的徒然无益"},{"en":"a sense of futility","cn":"徒劳感"}],"oxford":{"phon":"fjuːˈtɪləti","pos":"noun","senses":[{"en":"the fact of having no purpose because there is no chance of success","cn":"徒劳无功，无功而无过","ex":{"en":"a sense of futility","cn":"徒劳感"}}]}},"fuse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"保险丝;熔丝","en":"A fuse is a safety device in an electric plug or circuit. It contains a piece of wire which melts when there is a fault so that the flow of electricity stops.","ex":{"en":"The fuse blew as he pressed the button to start the motor","cn":"他按下按钮启动马达的时候保险丝烧断了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(电器等)因保险丝熔断而停止工作","en":"When an electric device fuses or when you fuse it, it stops working because of a fault.","ex":{"en":"The wire snapped at the wall plug and the light fused","cn":"墙上插座的电线短路烧断了保险丝，电灯跟着灭了。"}},{"pos":"N-COUNT 可数名词","cn":"导火线;引信;信管","en":"A fuse is a device on a bomb or firework which delays the explosion so that people can move a safe distance away.","ex":{"en":"A bomb was deactivated at the last moment, after the fuse had been lit.","cn":"炸弹在导火索已经点燃的最后一刻被解爆了。"}},{"pos":"V-RECIP-ERG","cn":"(使)熔接;(使)熔合;(使)结合","en":"When things fuse or are fused, they join together physically or chemically, usually to become one thing. You can also say that one thing fuses with another.","ex":{"en":"The skull bones fuse between the ages of fifteen and twenty-five","cn":"头骨在 15 至 25 岁之间长合。"}},{"pos":"V-RECIP-ERG","cn":"(使)(不同特质、思想等)合二为一，合为一体","en":"If something fuses two different qualities, ideas, or things, or if they fuse, they join together, especially in order to form a pleasing or satisfactory combination.","ex":{"en":"His music fused the rhythms of jazz with classical forms","cn":"他的音乐把爵士乐的节奏和古典乐的形式结合在了一起。"}},{"pos":"PHRASE 短语","cn":"勃然大怒;大发雷霆","en":"If you blow a fuse, you suddenly become very angry and are unable to stay calm.","ex":{"en":"For all my experience, I blew a fuse in the quarter-final and could have been sent off.","cn":"尽管已经是老经验了，我还是在四分之一决赛的时候按捺不住发了脾气，差点就被罚出场。"}},{"pos":"PHRASE 短语","cn":"(突然)触发，启动，激活","en":"If someone or something lights the fuse of a particular situation or activity, they suddenly get it started.","ex":{"en":"Hopes for an early cut in German interest rates lit the market's fuse early on.","cn":"对德国很快将会降低利率的期望使得市场早早启动了。"}},{"pos":"PHRASE 短语","cn":"容易发怒;动辄发火","en":"If you say that someone has a short fuse or is on a short fuse you mean that they are quick to react angrily when something goes wrong.","ex":{"en":"I have a very short fuse and a violent temper.","cn":"我容易发怒，脾气暴躁。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"easily annoyed by unimportant things, especially because you already feel bad-tempered about something","cn":""},{"en":"someone who is touchy is easily offended and made angry by things, so you have to be careful what you say to them","cn":""},{"en":"an old person who is crotchety becomes angry about unimportant things and complains a lot","cn":""}]},"vocab":{"pos":"1 n v 2 n 3 v","senses":[{"en":"A fuse is something that burns in order to ignite a bomb. Do you see anything near you that resembles a bundle of dynamite sticks with a fuse burning down? If so, stop reading this and GET OUT OF HERE!"}]},"collocations":{"phrases":["ADJ. short | long, slow | safety","VERB + FUSE set He set the fuse to thirty minutes. | light 2 in an electric circuit","ADJ. 5-amp, 10-amp, 13-amp, etc.","VERB + FUSE fit Make sure that the correct fuse is fitted. | change, replace | blow When the machine was switched on it blew a fuse.","FUSE + VERB blow Fuses blow if they are overloaded.","FUSE + NOUN wire | box The fire started in the fuse box downstairs."]},"media":{"img":["media/ldoce/img/fuses.jpg"],"uk":"media/ldoce/hwd/bre/9/brelasdefuse.mp3","us":"media/ldoce/hwd/ame/a/fuse1.mp3"},"examples":[{"en":"Our different ideas fused into a plan.","cn":"我们不同的想法融合成一项计划。"},{"en":"The bombs inside were on a one-hour fuse.","cn":"炸弹内装有一小时起爆的引信。"}],"oxford":{"phon":"fjuːz","pos":"noun","senses":[{"en":"a small wire or device inside a piece of electrical equipment that breaks and stops the current if the flow of electricity is too strong","cn":"熔断器；保险丝","ex":{"en":"to change a fuse","cn":"换保险丝"}},{"en":"a long piece of string or paper that is lit to make a bomb or a firework explode","cn":"导火线；导火索","lab":"North American English also"},{"en":"a device that makes a bomb explode when it hits something or at a particular time","cn":"引信；信管；雷管","lab":"North American English also","ex":{"en":"He set the fuse to three minutes.","cn":"他把引信设定为三分钟起爆。"}},{"en":"when one thing fuses with another, or two things fuse or are fused, they are joined together to form a single thing","cn":"（使）融合，结合","g":"[intransitive, transitive]","lab":"formal or specialist","ex":{"en":"As they heal, the bones will fuse together.","cn":"骨头愈合时将会连接在一起。"},"pos":"verb"},{"en":"when a substance, especially metal, fuses, or you fuse it, it is heated until it melts and joins with something else","cn":"（使）熔解，熔接","g":"[intransitive, transitive]","lab":"specialist","pos":"verb"},{"en":"to stop working or to make something stop working because a fuse melts","cn":"（使保险丝熔断而）停止工作","g":"[intransitive, transitive]","lab":"British English","ex":{"en":"The lights have fused.","cn":"保险丝烧断，灯都灭了。"},"pos":"verb"},{"en":"to put a fuse in a circuit or in a piece of equipment","cn":"在（电路或电器）中安装保险丝","g":"[transitive, usually passive]","ex":{"en":"Is this plug fused?","cn":"这个插头有没有安装保险丝？"},"pos":"verb"}]}}});
